// Builds an OpenRouter (OpenAI-compatible) request from the still frames the browser sends
const MODELS = ['meta/muse-spark-1.3', 'anthropic/claude-sonnet-5.5', 'nvidia/nemotron-3.5-super-vl:free'];   // first = primary, rest = automatic fallbacks
const MAX_MB = 12;

const item = $input.first();
const bin = item.binary || {};
const body = item.json.body || item.json;
const player = String(body.player || 'Unknown').trim() || 'Unknown';
const gameType = String(body.game_type || '8-ball');
const tableId = String(body.table || body.table_id || 'T1').trim().toUpperCase();
const chosen = String(body.model || '').trim();            // the test page can pick a model for A/B tests
const models = chosen ? [chosen, ...MODELS.filter(m => m !== chosen)].slice(0, 3) : MODELS;

const frames = []; let total = 0; let diffUrl = null;
for (const key of Object.keys(bin)) {
  if (key === 'frame_diff') { const db = await this.helpers.getBinaryDataBuffer(0, key); diffUrl = `data:image/jpeg;base64,${db.toString('base64')}`; continue; }
  if (!key.startsWith('frame_')) continue;            // the full video is not used with OpenRouter
  const meta = bin[key];
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  total += buf.length;
  const t = parseFloat(String(meta.fileName || '').replace(/[^0-9.]/g, '')) || 0;
  frames.push({ order: key === 'frame_start' ? -1 : key === 'frame_end' ? 1e9 : t, t, url: `data:${meta.mimeType || 'image/jpeg'};base64,${buf.toString('base64')}` });
}
frames.sort((a, b) => a.order - b.order);
if (frames.length < 2) return [{ json: { error: 'No frames received. Open the test page in Chrome so it can grab frames from the video.' } }];
if (total / 1048576 > MAX_MB) return [{ json: { error: 'Frames are too large. Lower the frame size on the test page.' } }];

const prompt = `You are a strict billiards referee. Analyse ONE ${gameType} shot from ${frames.length} still frames in time order.
The FIRST frame is the table before the shot, the LAST frame is after all balls stopped.
Pocket names are relative to the image as displayed: top-left, top-middle, top-right, bottom-left, bottom-middle, bottom-right.

Work in this order:
1. FIRST vs LAST frame: list each ball (colour, solid/stripe/cue/8) present in the first frame but missing in the last. Only these were pocketed.${diffUrl ? ' Use the CHANGE MAP to find where things changed: a pocketed ball leaves ONE white spot (its old position); a ball that moved leaves TWO spots (old and new position).' : ''}
   The cue ball is the plain white ball with no number or stripe. Before calling it missing, search the WHOLE cloth in the last frame and say where it is in "cue_ball_after". It is a scratch ONLY if it is truly not on the table.
2. Use the middle frames to follow the cue ball: which ball it hit first, where balls travelled.
3. Then give the verdict. It MUST agree with steps 1-2. Never claim a ball was pocketed if it is still visible in the last frame.
If something happens between frames and you cannot see it, say so and lower confidence.

Reply with ONLY this JSON, no other text:
{
  "missing_after": [string],
  "cue_ball_after": string,                 // where the cue ball is in the LAST frame, or "not visible"
  "timeline": [{"t": string, "event": string}],
  "shot_detected": boolean,
  "first_contact": string or null,
  "target_ball": string or null,
  "intended_pocket": string or null,
  "potted_balls": [string],                 // name each as "solid N", "stripe N", "8 ball" or "cue ball" (use "solid ?" / "stripe ?" + colour if the number is unreadable)
  "target_potted": boolean,
  "miss_quality": "potted" | "close" | "medium" | "far",
  "cue_ball_outcome": "good_position" | "ok_position" | "bad_position" | "scratch",
  "difficulty": "easy" | "medium" | "hard",
  "foul": boolean,
  "foul_reason": string or null,
  "observations": string,
  "tip": string,
  "confidence": number
}`;

const content = [];
frames.forEach((f, i) => {
  const label = i === 0 ? 'BEFORE' : i === frames.length - 1 ? 'AFTER (balls stopped)' : `t=${f.t.toFixed(2)}s`;
  content.push({ type: 'text', text: `Frame ${i + 1} (${label}):` }, { type: 'image_url', image_url: { url: f.url } });
});
if (diffUrl) content.push({ type: 'text', text: 'CHANGE MAP (white = pixels that changed between BEFORE and AFTER, black = unchanged):' }, { type: 'image_url', image_url: { url: diffUrl } });
content.push({ type: 'text', text: prompt });

return [{ json: {
  player, table_id: tableId, game_type: gameType, has_frames: true, frame_count: frames.length, used_video: false,
  llm_body: { model: models[0], models, temperature: 0, max_tokens: 8000, reasoning: { effort: 'low' }, response_format: { type: 'json_object' }, messages: [{ role: 'user', content }] },
}}];

// Turns Gemini's observations into a deterministic 0-100 shot score
const req = $('Prepare AI Request').first().json;
const r = $input.first().json;
if (req.error) return [{ json: { ok: false, table_id: req.table_id, player: req.player || null, error: req.error } }];

if (r.error) {
  const m = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return [{ json: { ok: false, table_id: req.table_id, player: req.player, error: 'AI request failed: ' + m } }];
}
const choice = (r.choices || [])[0] || {};
const finish = choice.finish_reason || choice.native_finish_reason || null;
let text = choice.message?.content ?? '';
if (Array.isArray(text)) text = text.map(p => p.text || '').join('');
text = String(text);

// Robust JSON extraction: handles <think> blocks, code fences, prose around the JSON
function extractJson(t) {
  t = t.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '');
  try { return JSON.parse(t.trim()); } catch (e) {}
  const cands = [];
  for (let i = 0; i < t.length; i++) {
    if (t[i] !== '{') continue;
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < t.length; j++) {
      const c = t[j];
      if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
      if (c === '"') inStr = true;
      else if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { cands.push(t.slice(i, j + 1)); i = j; break; } }
    }
  }
  for (const c of cands.reverse()) { try { const o = JSON.parse(c); if (o && 'shot_detected' in o) return o; } catch (e) {} }
  return null;
}
const o = extractJson(text);
if (!o) {
  const why = !text.trim() ? (finish === 'length' ? 'the model ran out of tokens while thinking' : 'the model returned an empty answer')
            : finish === 'length' ? 'the answer was cut off (too long)' : 'the answer was not valid JSON';
  return [{ json: { ok: false, table_id: req.table_id, player: req.player, model: r.model || null, finish_reason: finish,
    error: `Could not read AI answer: ${why} (model: ${r.model || '?'}). Try again or pick another model.`, raw: text.slice(0, 400) } }];
}
if (!o.shot_detected) {
  return [{ json: { ok: false, table_id: req.table_id, player: req.player, error: 'No shot detected in this clip', ai: o } }];
}

const cueAfter = String(o.cue_ball_after || '').toLowerCase();
const cueSeen = cueAfter && !/not visible|missing|pocket|none|n\/a/.test(cueAfter);
if (cueSeen) {                                            // model says it can see the cue ball after the shot -> cannot be a scratch
  o.missing_after = (o.missing_after || []).filter(b => !/cue|white/i.test(b));
  if (o.cue_ball_outcome === 'scratch') { o.cue_ball_outcome = 'ok_position'; o.confidence = Math.min(Number(o.confidence) || 0, 0.5); }
  if (o.foul && /scratch|cue ball/i.test(o.foul_reason || '')) { o.foul = false; o.foul_reason = null; }
}
const miss = (o.missing_after || []).join(' ').toLowerCase();
if (/cue|white/.test(miss)) { o.cue_ball_outcome = 'scratch'; o.foul = true; o.foul_reason = o.foul_reason || 'cue ball scratched'; }
if (req.has_frames && o.target_potted && o.target_ball && !miss.includes(String(o.target_ball).toLowerCase().split(' (')[0].split(' ').pop())) {
  o.confidence = Math.min(Number(o.confidence) || 0, 0.5); // claims a pot the after-frame doesn't confirm
}

// ---- scoring rubric (code decides the number, AI only describes the shot) ----
const POT = { potted: 55, close: 25, medium: 12, far: 0 };
const CUE = { good_position: 25, ok_position: 15, bad_position: 5, scratch: 0 };
const DIFF = { easy: 0, medium: 10, hard: 20 };

const pot = o.target_potted ? 55 : (POT[o.miss_quality] ?? 0);
const cue = CUE[o.cue_ball_outcome] ?? 0;
const diff = DIFF[o.difficulty] ?? 0;
const diffBonus = o.target_potted ? diff : Math.round(diff / 2);
let score = Math.min(100, pot + cue + diffBonus);
if (o.foul) score = Math.min(score, 10);

const grade = score >= 85 ? 'Excellent' : score >= 70 ? 'Good' : score >= 50 ? 'Okay' : 'Needs work';
const confidence = Math.max(0, Math.min(1, Number(o.confidence) || 0));

return [{ json: {
  ok: true,
  player: req.player,
  table_id: req.table_id,
  game_type: req.game_type,
  score,
  grade,
  breakdown: { pot, cue_ball: cue, difficulty_bonus: diffBonus, foul: !!o.foul },
  target_ball: o.target_ball || null,
  intended_pocket: o.intended_pocket || null,
  potted_balls: o.potted_balls || [],
  difficulty: o.difficulty,
  cue_ball_outcome: o.cue_ball_outcome,
  foul_reason: o.foul ? (o.foul_reason || 'foul') : null,
  observations: o.observations || '',
  first_contact: o.first_contact || null,
  cue_ball_after: o.cue_ball_after || null,
  missing_after: o.missing_after || [],
  timeline: Array.isArray(o.timeline) ? o.timeline.slice(0, 12) : [],
  used_frames: !!req.has_frames,
  frame_count: req.frame_count || 0,
  model: r.model || null,
  used_video: !!req.used_video,
  tip: o.tip || '',
  confidence,
  needs_review: confidence < 0.6,
  scored_at: new Date().toISOString(),
}}];

// Combines the AI score with the game-engine result (turn, groups, winner)
const shot = $('Score Shot').first().json;
const r = $input.first().json || {};
const applied = r.ok === true;
const errMsg = typeof r.error === 'string' ? r.error : (r.error && r.error.message) || null;
return [{ json: {
  ...shot,
  player: r.shot ? r.shot.player : shot.player,
  shot_id: r.shot ? r.shot.id : null,
  game: r.game || null,
  skipped: !!r.skipped,
  table: r.table || null,
  apply_error: applied ? null : (errMsg || 'Could not update the game state (is the workflow active?)'),
}}];

