function leaderboard() {
  const rows = Object.values(sd.players).filter(p => p.matches > 0 || p.shots > 0).map(p => ({
    name: p.name, rating: p.rating, matches: p.matches, wins: p.wins, losses: p.losses,
    win_rate: p.matches ? Math.round(p.wins / p.matches * 100) : null,
    avg_shot: p.shots ? Math.round(p.score_sum / p.shots) : null, shots: p.shots, fouls: p.fouls, best_shot: p.best, badges: [],
  }));
  const top = (f, filter) => { const c = rows.filter(filter).sort((a, b) => f(b) - f(a))[0]; return c; };
  const sharp = top(r => r.avg_shot, r => r.shots >= 5); if (sharp) sharp.badges.push('sharpshooter');
  const fair = top(r => -r.fouls / r.shots, r => r.shots >= 5); if (fair) fair.badges.push('fair_play');
  const best = top(r => r.best_shot, r => r.shots >= 1); if (best && best.best_shot >= 85) best.badges.push('best_shot');
  return rows.sort((a, b) => b.rating - a.rating || (b.avg_shot || 0) - (a.avg_shot || 0)).slice(0, 50);
}

